import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldContent from "@marko-ui/shadcn/ui/field/field-content.marko";
import FieldDescription from "@marko-ui/shadcn/ui/field/field-description.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import Switch from "@marko-ui/shadcn/ui/switch/switch.marko";

<div class="w-full max-w-sm">
  <Field orientation="horizontal">
    <FieldContent>
      <FieldLabel for="switch-focus-mode">Share across devices</FieldLabel>
      <FieldDescription>
        Focus is shared across devices, and turns off when you leave the app.
      </FieldDescription>
    </FieldContent>
    <Switch id="switch-focus-mode" ids={ hiddenInput: "switch-focus-mode" }/>
  </Field>
</div>

import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldContent from "@marko-ui/shadcn/ui/field/field-content.marko";
import FieldDescription from "@marko-ui/shadcn/ui/field/field-description.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import Switch from "@marko-ui/shadcn/ui/switch/switch.marko";

<div class="w-full max-w-sm">
  <Field orientation="horizontal" invalid>
    <FieldContent>
      <FieldLabel for="switch-terms">Accept terms and conditions</FieldLabel>
      <FieldDescription>You must accept the terms and conditions to continue.</FieldDescription>
    </FieldContent>
    <Switch id="switch-terms" ids={ hiddenInput: "switch-terms" } invalid/>
  </Field>
</div>

import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldContent from "@marko-ui/shadcn/ui/field/field-content.marko";
import FieldDescription from "@marko-ui/shadcn/ui/field/field-description.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import Switch from "@marko-ui/shadcn/ui/switch/switch.marko";

<div dir="rtl" class="w-full max-w-sm">
  <Field orientation="horizontal">
    <FieldContent>
      <FieldLabel for="switch-focus-mode-rtl" dir="rtl">المشاركة عبر الأجهزة</FieldLabel>
      <FieldDescription dir="rtl">
        يتم مشاركة التركيز عبر الأجهزة، ويتم إيقاف تشغيله عند مغادرة التطبيق.
      </FieldDescription>
    </FieldContent>
    <Switch id="switch-focus-mode-rtl" ids={ hiddenInput: "switch-focus-mode-rtl" } dir="rtl"/>
  </Field>
</div>
